def find_member(members, name):
    """Return the index of the member called name, or -1."""
    for i in range(len(members)):
        if members[i][0] == name:
            return i
    return -1

def total_points(members):
    """Return the sum of all members' points."""
    total = 0
    for m in members:
        total = total + m[2]
    return total

def format_member(m):
    """Return the display line for one member, e.g. 'Ada (year 9) - 12 points'."""
    return m[0] + " (year " + str(m[1]) + ") - " + str(m[2]) + " points"

def top_member(members):
    """Return the name of the member with the most points, or '' if the list is empty."""
    if len(members) == 0:
        return ""
    best = members[0]
    for m in members:
        if m[2] > best[2]:
            best = m
    return best

